import torch
import torch.distributed as dist
import torch.nn as nn
import torch.nn.functional as F


def _world_size():
    if dist.is_available() and dist.is_initialized():
        return dist.get_world_size()
    return 1


def _rank():
    if dist.is_available() and dist.is_initialized():
        return dist.get_rank()
    return 0


# ---------------------------------------------------------------------------
# Autograd-aware communication primitives
# ---------------------------------------------------------------------------
class _CopyToParallelRegion(torch.autograd.Function):
    """Forward: identity. Backward: all-reduce the gradient."""

    @staticmethod
    def forward(ctx, x):
        return x

    @staticmethod
    def backward(ctx, grad):
        if _world_size() == 1:
            return grad
        grad = grad.contiguous().clone()
        dist.all_reduce(grad, op=dist.ReduceOp.SUM)
        return grad


class _ReduceFromParallelRegion(torch.autograd.Function):
    """Forward: all-reduce (sum). Backward: identity."""

    @staticmethod
    def forward(ctx, x):
        if _world_size() == 1:
            return x
        x = x.contiguous().clone()
        dist.all_reduce(x, op=dist.ReduceOp.SUM)
        return x

    @staticmethod
    def backward(ctx, grad):
        return grad


class _GatherFromParallelRegion(torch.autograd.Function):
    """Forward: all-gather along last dim. Backward: take local slice."""

    @staticmethod
    def forward(ctx, x):
        ws = _world_size()
        if ws == 1:
            return x
        x = x.contiguous()
        parts = [torch.empty_like(x) for _ in range(ws)]
        dist.all_gather(parts, x)
        return torch.cat(parts, dim=-1).contiguous()

    @staticmethod
    def backward(ctx, grad):
        ws = _world_size()
        if ws == 1:
            return grad
        return torch.chunk(grad, ws, dim=-1)[_rank()].contiguous()


class _ScatterToParallelRegion(torch.autograd.Function):
    """Forward: take local slice along last dim. Backward: all-gather."""

    @staticmethod
    def forward(ctx, x):
        ws = _world_size()
        if ws == 1:
            return x
        return torch.chunk(x, ws, dim=-1)[_rank()].contiguous()

    @staticmethod
    def backward(ctx, grad):
        ws = _world_size()
        if ws == 1:
            return grad
        grad = grad.contiguous()
        parts = [torch.empty_like(grad) for _ in range(ws)]
        dist.all_gather(parts, grad)
        return torch.cat(parts, dim=-1).contiguous()


# ---------------------------------------------------------------------------
# Layers
# ---------------------------------------------------------------------------
class ColumnParallelLinear(nn.Module):
    """Y = X A^T + b, with A (out_features x in_features) split along the
    output dimension (columns of the math-form weight X @ W)."""

    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.world_size = _world_size()
        self.rank = _rank()
        assert out_features % self.world_size == 0, \
            "out_features must be divisible by world_size"
        self.output_size_per_partition = out_features // self.world_size

        assert tuple(master_weight.shape) == (out_features, in_features), \
            "master_weight must have shape (out_features, in_features)"
        start = self.rank * self.output_size_per_partition
        end = start + self.output_size_per_partition
        with torch.no_grad():
            shard = master_weight.detach()[start:end, :].clone().contiguous()
        self.weight = nn.Parameter(shard)

        if bias:
            self.bias = nn.Parameter(
                torch.zeros(self.output_size_per_partition,
                            dtype=shard.dtype, device=shard.device))
        else:
            self.register_parameter("bias", None)

    def forward(self, x):
        x = _CopyToParallelRegion.apply(x)
        local_out = F.linear(x, self.weight, self.bias)
        return _GatherFromParallelRegion.apply(local_out)


class RowParallelLinear(nn.Module):
    """Y = X A^T + b, with A (out_features x in_features) split along the
    input dimension (rows of the math-form weight X @ W). Partial outputs
    are summed via all-reduce; bias is full on every rank."""

    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.world_size = _world_size()
        self.rank = _rank()
        assert in_features % self.world_size == 0, \
            "in_features must be divisible by world_size"
        self.input_size_per_partition = in_features // self.world_size

        assert tuple(master_weight.shape) == (out_features, in_features), \
            "master_weight must have shape (out_features, in_features)"
        start = self.rank * self.input_size_per_partition
        end = start + self.input_size_per_partition
        with torch.no_grad():
            shard = master_weight.detach()[:, start:end].clone().contiguous()
        self.weight = nn.Parameter(shard)

        if bias:
            self.bias = nn.Parameter(
                torch.zeros(out_features, dtype=shard.dtype,
                            device=shard.device))
        else:
            self.register_parameter("bias", None)

    def forward(self, x):
        if x.shape[-1] == self.input_size_per_partition and self.world_size > 1 \
                and self.input_size_per_partition != self.in_features:
            # Input is already partitioned.
            x_local = x
        else:
            x_local = _ScatterToParallelRegion.apply(x)
        partial = F.linear(x_local, self.weight)
        out = _ReduceFromParallelRegion.apply(partial)
        if self.bias is not None:
            out = out + self.bias
        return out
